-- Executed 2026-11-10. Alias inserts reconcile pending positions through the existing trigger.
INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias)
SELECT i.id,m.alias,lower(trim(m.alias)) FROM jsonb_to_recordset($a$[{"slug":"ajo","alias":"dientes de ajo"},{"slug":"ajo","alias":"dientes de ajo picados"},{"slug":"ajo","alias":"Ajo pelado, unos 2 dientes"},{"slug":"cilantro","alias":"cilantro fresco, picado"},{"slug":"perejil","alias":"perejil fresco, picado"},{"slug":"perejil","alias":"perejil picado"},{"slug":"aceite-de-canola","alias":"aceite de canola"},{"slug":"aceite-de-canola","alias":"aceite de canola para freír"},{"slug":"aceite-de-canola","alias":"aceite de canola para freír (no se consume entero)"},{"slug":"albahaca-fresca","alias":"hojas de albahaca fresca"},{"slug":"albahaca-fresca","alias":"hojas de albahaca fresca, para servir"},{"slug":"albahaca-fresca","alias":"hojas de albahaca fresca, lavadas y secas"},{"slug":"huevo","alias":"huevo grande"},{"slug":"huevo","alias":"huevo grande, a temperatura ambiente"},{"slug":"huevo","alias":"huevo entero sin cáscara, pesado"},{"slug":"harina-de-trigo","alias":"harina de trigo de uso común"},{"slug":"agua","alias":"agua caliente"},{"slug":"agua","alias":"agua para cocer"},{"slug":"caldo-de-verduras","alias":"caldo de verduras caliente"},{"slug":"carne-molida-de-res","alias":"carne de res molida"},{"slug":"carne-molida-de-res","alias":"carne de res molida (85 % magra)"},{"slug":"crema-de-leche","alias":"crema de leche, para decorar"},{"slug":"laurel","alias":"hoja de laurel"},{"slug":"laurel","alias":"laurel seco, para retirar"},{"slug":"yema-de-huevo","alias":"yemas de huevo"},{"slug":"yema-de-huevo","alias":"yemas de huevo, unas 3 grandes; pesar 51 g"},{"slug":"zanahoria","alias":"zanahorias"},{"slug":"aguacate","alias":"aguacate, pulpa"},{"slug":"aguacate","alias":"aguacates maduros"},{"slug":"aguacate","alias":"aguacates grandes bien maduros"},{"slug":"pimenton-dulce","alias":"pimentón dulce molido"},{"slug":"arandanos","alias":"arándanos, limpios y secos"},{"slug":"fresas","alias":"fresas, limpias y secas"},{"slug":"limon","alias":"zumo de limón recién exprimido"},{"slug":"limon","alias":"zumo de limón recién exprimido y colado, sin semillas"},{"slug":"limon","alias":"zumo de limón sin semillas"},{"slug":"limon","alias":"zumo de limón recién exprimido, sin semillas"},{"slug":"zumo-de-pina","alias":"jugo de piña"}]$a$::jsonb) m(slug text,alias text)
JOIN public.ingredients i ON i.slug=m.slug AND i.status='canonical'
WHERE NOT EXISTS(SELECT 1 FROM public.ingredient_aliases a WHERE a.normalized_alias=lower(trim(m.alias)))
AND NOT EXISTS(SELECT 1 FROM public.ingredients c WHERE c.status='canonical' AND c.id<>i.id AND lower(coalesce(c.normalized_name,c.name))=lower(trim(m.alias)))
RETURNING alias;
UPDATE public.recipes SET notes=replace(notes,'; no afirmar prueba de cocina propia.','.'), steps=jsonb_set(steps,'{7,content}',to_jsonb(replace(steps->7->>'content','y unta la piel y acomoda','y unta la piel. Acomoda'))) WHERE id='0c8a361b-cb9a-424b-adc2-e27ae183062f' RETURNING id;
UPDATE public.recipes SET notes=replace(notes,'No kitchen-tested claim. ','') WHERE id='1071bdb9-4e2a-462b-8a1a-e736c2b377d0' RETURNING id;
